import re
seq=[]
for line in open("region.fasta"):
    line=line.strip()
    if not line.startswith(">"): seq.append(line)
s="".join(seq).upper()
comp=str.maketrans("ACGT","TGCA")
def rc(x): return x.translate(comp)[::-1]

# lambda-like CI-interactive operator palindrome / CAP / LexA style motifs, with 0 and 1 mismatch
mots = {
 "CAP TGTGA(N6)TCACA": r"TGTGA[ACGT]{6}TCACA",
 "LexA CTGT(N8)ACAG":  r"CTGT[ACGT]{8}ACAG",
 "lexA-like 2":        r"ctgt[ACGT]{8}acag",
 "sigma70 -10 TATAAT": r"TATAAT",
 "sigma70 -35 TTGACA": r"TTGACA",
 "IS10/near-perfect 18pal":  None,
}
for name,p in mots.items():
    if p is None: continue
    hits=[]
    for strand,ss in [("fwd",s),("rev",rc(s))]:
        for m in re.finditer(p, ss, re.IGNORECASE):
            hits.append((strand,m.start()+1,m.group()))
    print(name, hits)

# 1-mismatch LexA (CTGT N8 ACAG) to see background
pat="CTGT[ACGT]{8}ACAG"
def withmm(s,p,mm=1):
    # brute-force all placements with levenshtein <= mm
    L=len(p); hits=[]
    for i in range(len(s)-L+1):
        w=s[i:i+L]
        d=sum(1 for a,b in zip(w,p) if a!=b)
        if d<=mm: hits.append((i+1,w,d))
    return hits
print("\nLexA motif with <=1 mismatch:", withmm(s,pat,1))
print("CAP motif with <=1 mismatch:", withmm(s,"TGTGA[ACGT]{6}TCACA" and "TGTGANNNNNNTCACA",1))

# longest perfect palindrome anywhere (allows loop) impact factor
mx=0; pos=None
for L in range(len(s),0,-1):
    hit=False
    for i in range(len(s)-L+1):
        if s[i:i+L]==rc(s[i:i+L]):
            if L>mx:
                mx=L; pos=(i+1,s[i:i+L])
            hit=True
    if hit: break
print("\nlongest perfect palindrome:",mx,"at",pos)
